export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // tenant -> key -> original receipt. Nested maps keep tenant and key scoping
  // unambiguous (no delimiter collisions between tenant and key).
  readonly #byTenant = new Map<string, Map<string, Receipt>>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // The check-and-insert below has no await in between, so concurrent calls
    // for the same tenant/key cannot both debit.
    let keys = this.#byTenant.get(tenant);
    if (!keys) { keys = new Map(); this.#byTenant.set(tenant, keys); }
    const original = keys.get(key);
    if (original) {
      if (original.cents !== cents) throw new Error('key conflict');
      return original;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    keys.set(key, receipt);
    return receipt;
  }
}

